CREATE TABLE employees (
    id INT PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    department VARCHAR(50) NOT NULL,
    salary INT NOT NULL
);
INSERT INTO employees VALUES (1, 'Ana', 'AI', 60000), (2, 'Ravi', 'Backend', 50000);
SELECT id, name, department, salary FROM employees;

CREATE TABLE accounts (
    account_id INT PRIMARY KEY,
    balance NUMERIC(12, 2) NOT NULL,
    is_verified BOOLEAN NOT NULL,
    opened_at TIMESTAMPTZ NOT NULL
);
INSERT INTO accounts VALUES (101, 15420.50, TRUE, '2026-01-15 10:00:00+00');
SELECT account_id, balance, is_verified FROM accounts;

CREATE TABLE departments (
    id INT PRIMARY KEY,
    dept_name VARCHAR(50) NOT NULL
);
CREATE TABLE staff (
    staff_id INT PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    dept_id INT REFERENCES departments(id)
);
INSERT INTO departments VALUES (10, 'Engineering');
INSERT INTO staff VALUES (1, 'Kiran', 10);
SELECT staff.name, departments.dept_name FROM staff JOIN departments ON staff.dept_id = departments.id;

-- 3NF compliant design separating departments from employee records
CREATE TABLE depts (id INT PRIMARY KEY, name VARCHAR(50), building VARCHAR(50));
CREATE TABLE workers (id INT PRIMARY KEY, name VARCHAR(50), dept_id INT REFERENCES depts(id));
INSERT INTO depts VALUES (1, 'AI Lab', 'Tower B');
INSERT INTO workers VALUES (101, 'Maya', 1);
SELECT workers.name, depts.building FROM workers JOIN depts ON workers.dept_id = depts.id;

CREATE TABLE inventory (
    sku VARCHAR(20) PRIMARY KEY,
    stock INT NOT NULL,
    status VARCHAR(20) NOT NULL
);
INSERT INTO inventory VALUES ('SKU-01', 15, 'available'), ('SKU-02', 0, 'out_of_stock');
SELECT sku, stock FROM inventory WHERE status = 'available';
